const html2pptx = require('./kimi-skills/pptx/scripts/html2pptx.js');

async function build() {
  const pptx = new pptxgen();
  pptx.layout = 'LAYOUT_16x9';
  pptx.author = 'Kimi';
  pptx.title = 'Attention Is All You Need';

  // Slides 1-6
